import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"관리자 승인 기반 Passkey 로그인 구현 계획_20260608","description":"","frontmatter":{},"headers":[],"relativePath":"관리자 승인 기반 Passkey 로그인 구현 계획_20260608.md","filePath":"관리자 승인 기반 Passkey 로그인 구현 계획_20260608.md"}'),s={name:"관리자 승인 기반 Passkey 로그인 구현 계획_20260608.md"};function t(d,e,r,c,u,n){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="관리자-승인-기반-passkey-로그인-구현-계획-20260608" tabindex="-1">관리자 승인 기반 Passkey 로그인 구현 계획_20260608 <a class="header-anchor" href="#관리자-승인-기반-passkey-로그인-구현-계획-20260608" aria-label="Permalink to &quot;관리자 승인 기반 Passkey 로그인 구현 계획_20260608&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ul><li><code>/guard</code>는 기존 이름/전화번호 로그인을 유지하고, 로그인 후 경비원이 “패스키 등록 요청”을 보낼 수 있게 한다.</li><li>관리자가 승인하면 서버가 해당 경비원에게 Supabase Auth 계정을 연결하고, 경비원은 승인된 상태에서 1회 등록 링크/세션을 통해 <code>registerPasskey()</code>를 실행한다.</li><li>이후 <code>/guard</code> 로그인 화면에는 “패스키로 로그인” 버튼을 추가하고, 성공 시 Supabase Auth <code>user.id</code>를 <code>employees.auth_user_id</code>에 매핑해 기존 <code>GuardSession</code> 형태로 전환한다.</li><li>Supabase Passkey는 현재 beta/experimental 기능이므로 기존 이름/전화번호 로그인은 fallback으로 계속 둔다.</li></ul><h2 id="key-changes" tabindex="-1">Key Changes <a class="header-anchor" href="#key-changes" aria-label="Permalink to &quot;Key Changes&quot;">​</a></h2><h3 id="db" tabindex="-1">DB <a class="header-anchor" href="#db" aria-label="Permalink to &quot;DB&quot;">​</a></h3><ul><li><code>employees</code>에 <code>auth_user_id uuid unique null</code>, <code>passkey_enabled boolean default false</code> 추가.</li><li><code>guard_passkey_requests</code> 테이블 추가: <code>employee_id</code>, <code>status</code>(<code>pending|approved|rejected|registered|revoked</code>), <code>requested_at</code>, <code>reviewed_at</code>, <code>reviewed_by</code>, <code>registered_at</code>.</li><li>RLS는 관리자/서버 API 경유만 허용하고, 클라이언트 직접 쓰기는 막는다.</li></ul><h3 id="supabase-auth" tabindex="-1">Supabase Auth <a class="header-anchor" href="#supabase-auth" aria-label="Permalink to &quot;Supabase Auth&quot;">​</a></h3><ul><li>Dashboard에서 Authentication → Passkeys 활성화.</li><li>RP ID는 운영 도메인으로 고정: 기본값 <code>ollbareun.vercel.app</code>.</li><li>RP Origins: <code>https://ollbareun.vercel.app</code>, 개발용 <code>http://localhost:3000</code>.</li><li>서버 전용 <code>SUPABASE_SECRET_KEY</code>를 추가하고, service role/secret key는 브라우저에 노출하지 않는다.</li></ul><h3 id="client-auth" tabindex="-1">Client/Auth <a class="header-anchor" href="#client-auth" aria-label="Permalink to &quot;Client/Auth&quot;">​</a></h3><ul><li>기존 <code>src/lib/supabase.ts</code>는 데이터용으로 유지.</li><li>Passkey 전용 client를 별도 생성: <code>experimental: { passkey: true }</code>, <code>persistSession: true</code>.</li><li>등록 완료 후에는 Supabase Auth 세션을 <code>signOut()</code>하고, 앱은 기존 <code>sessionStorage</code> 기반 <code>GuardSession</code>을 계속 사용한다.</li></ul><h2 id="implementation-changes" tabindex="-1">Implementation Changes <a class="header-anchor" href="#implementation-changes" aria-label="Permalink to &quot;Implementation Changes&quot;">​</a></h2><h3 id="guard-main-profile" tabindex="-1"><code>/guard/main/profile</code> <a class="header-anchor" href="#guard-main-profile" aria-label="Permalink to &quot;`/guard/main/profile`&quot;">​</a></h3><ul><li>“패스키 등록 요청” 섹션 추가.</li><li>요청 상태 표시: 미요청, 승인 대기, 승인됨, 등록 완료, 거절됨.</li><li>승인됨 상태에서는 “이 기기에 패스키 등록” 버튼을 표시한다.</li></ul><h3 id="관리자-화면" tabindex="-1">관리자 화면 <a class="header-anchor" href="#관리자-화면" aria-label="Permalink to &quot;관리자 화면&quot;">​</a></h3><ul><li>직원 관리 또는 별도 메뉴에 “패스키 요청 관리” 목록 추가.</li><li>요청자 이름/전화번호/요청일/상태 표시.</li><li>승인/거절/해제 버튼 제공.</li></ul><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li><code>POST /api/guard/passkey-requests</code>: 기존 경비원 세션의 <code>employee.id</code>로 요청 생성.</li><li><code>GET /api/guard/passkey-requests/me</code>: 경비원 본인 요청 상태 조회.</li><li><code>PATCH /api/manager/guard-passkey-requests/[id]</code>: 관리자 승인/거절/해제.</li><li><code>POST /api/guard/passkeys/registration-link</code>: 승인된 경비원만 호출 가능. 서버가 Supabase Auth 사용자 생성/연결 후 일회성 Auth 링크를 발급.</li><li><code>POST /api/guard/passkeys/session</code>: <code>signInWithPasskey()</code> 성공 후 Supabase access token을 검증하고 기존 <code>GuardSession</code> 응답 생성.</li></ul><h3 id="guard" tabindex="-1"><code>/guard</code> <a class="header-anchor" href="#guard" aria-label="Permalink to &quot;`/guard`&quot;">​</a></h3><ul><li>기존 이름/전화번호 폼 위 또는 아래에 “패스키로 로그인” 버튼 추가.</li><li>클릭 시 <code>supabase.auth.signInWithPasskey()</code> 실행.</li><li>성공하면 <code>/api/guard/passkeys/session</code>으로 경비원 세션을 받아 <code>sessionStorage[&quot;ollbareun.guard.session&quot;]</code>에 저장하고 <code>/guard/main</code>으로 이동.</li><li>실패 시 기존 로그인 방식을 안내한다.</li></ul><h2 id="test-plan" tabindex="-1">Test Plan <a class="header-anchor" href="#test-plan" aria-label="Permalink to &quot;Test Plan&quot;">​</a></h2><h3 id="unit-api-tests" tabindex="-1">Unit/API tests <a class="header-anchor" href="#unit-api-tests" aria-label="Permalink to &quot;Unit/API tests&quot;">​</a></h3><ul><li>미승인 경비원은 등록 링크 발급 불가.</li><li>승인된 요청은 Auth 사용자와 <code>employees.auth_user_id</code>가 연결됨.</li><li>등록 완료 후 요청 상태가 <code>registered</code>로 변경됨.</li><li>Passkey 로그인 성공 시 기존 <code>GuardSession</code> 형태가 반환됨.</li><li>퇴직 직원, 미등록 직원, <code>auth_user_id</code> 미매핑 사용자는 거부됨.</li></ul><h3 id="component-tests" tabindex="-1">Component tests <a class="header-anchor" href="#component-tests" aria-label="Permalink to &quot;Component tests&quot;">​</a></h3><ul><li><code>/guard</code>에 패스키 로그인 버튼이 보임.</li><li>패스키 실패 시 오류 메시지를 표시하고 기존 로그인 폼은 유지됨.</li><li><code>/guard/main/profile</code>에서 상태별 버튼/문구가 올바르게 보임.</li><li>관리자 요청 목록에서 승인/거절 액션이 호출됨.</li></ul><h3 id="manual-verification" tabindex="-1">Manual verification <a class="header-anchor" href="#manual-verification" aria-label="Permalink to &quot;Manual verification&quot;">​</a></h3><ul><li><code>http://localhost:3000</code>에서 개발용 Origin으로 등록 테스트.</li><li>운영 배포 후 <code>https://ollbareun.vercel.app</code>에서 실제 기기 지문/Face ID/PIN 등록 및 로그인 테스트.</li><li>RP ID 변경 없이 운영 도메인이 고정되어 있는지 확인.</li></ul><h2 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h2><ul><li>관리자 인증은 현재 관리자 화면 접근 방식과 동일한 수준으로 보호한다고 가정한다.</li><li>관리자 승인 방식은 SMS/이메일 본인확인을 하지 않으므로, 운영상 관리자가 실제 경비원 요청인지 확인해야 한다.</li><li>Supabase Passkey API는 beta/experimental이므로 이름/전화번호 로그인은 제거하지 않는다.</li><li>운영 RP ID 기본값은 <code>ollbareun.vercel.app</code>으로 잡고, 실제 커스텀 도메인이 생기면 첫 등록 전에 최종 도메인으로 바꾼다.</li></ul>',28)])])}const m=a(s,[["render",t]]);export{p as __pageData,m as default};
